/* @socom-skeleton stub RemoveAll__7CEntityFv */
void CEntity::RemoveAll()
{
	/* 0x1ef010 (CMission::Close, ReOpen_Unload2): the recycle queue is dropped, every entity
	 * leaves m_list from the front and is deleted (virtual deleting dtor) - the recycler's
	 * entity only when its count runs out (then its entity and node are deleted and the
	 * recycler cleared) - the recycler is cleared again, entity ids restart at 0 and the
	 * three target lists are emptied.
	 * port: the recycler (file-local, an untyped placeholder) is never made (CreateRecycler
	 * is unwritten), so its branches are not written */
	m_recycle.clear();

	while (!m_list.empty())
	{
		CEntity* entity = m_list.front();
		m_list.pop_front();

		if (entity != NULL)
			delete entity;
	}

	nextEntityId = 0;
	m_target_inc.clear();
	m_target_rem.clear();
	m_target_add.clear();
}

/* @socom-skeleton stub PreTickAll__7CEntityFfPv */
bool CEntity::PreTickAll(float dT, void *)
{
	/* 0x1eeef0 (task entity_pre_tick 1.0): recycle one pending entity, refresh the
	   target lists, then every entity's PreTick */
	if (!m_recycle.empty())
		DoRecycleEntity(m_recycle.front());

	UpdateTargetList(false);

	for (CEntityList::iterator it = m_list.begin(); it != m_list.end(); ++it)
		(*it)->PreTick(dT);

	return false;
}

/* @socom-skeleton stub TickAll__7CEntityFfPv */
bool CEntity::TickAll(float dT, void *)
{
	/* 0x1eedb0 (task entity_tick 4.6): every entity's Tick. ELF quirk kept: PostPreTick
	   runs once per frame, on the first entity of the list only. */
	bool first = false;

	for (CEntityList::iterator it = m_list.begin(); it != m_list.end(); ++it)
	{
		CEntity* entity = *it;

		if (!first)
		{
			entity->PostPreTick(dT);
			first = true;
		}

		entity->Tick(dT);
	}

	return false;
}

/* @socom-skeleton stub PostTickAll__7CEntityFfPv */
bool CEntity::PostTickAll(float dT, void *)
{
	/* 0x1eec70 (task entity_post_tick 6.0): every entity's PostTick. ELF quirk kept:
	   PrePostTick runs once per frame, on the first entity of the list only. */
	bool first = false;

	for (CEntityList::iterator it = m_list.begin(); it != m_list.end(); ++it)
	{
		CEntity* entity = *it;

		if (!first)
		{
			entity->PrePostTick(dT);
			first = true;
		}

		entity->PostTick(dT);
	}

	return false;
}

